#include "bsp_key.h"

#define KEY_DEBOUNCE_MS 20

void bspKeyInit(void)
{
    // GPIO initialization is assumed to be handled in main.c generated by STM32CubeMX
}

KeyEvent bspKeyScan(void)
{
    static uint32_t last_scan_time = 0;

    static uint8_t K_0_last = GPIO_PIN_SET;
    static uint8_t K_1_last = GPIO_PIN_SET;
    static uint8_t K_2_last = GPIO_PIN_SET;
    static uint8_t K_3_last = GPIO_PIN_SET;
    static uint8_t K_4_last = GPIO_PIN_SET;
    static uint8_t K_5_last = GPIO_PIN_SET;
    static uint8_t K_6_last = GPIO_PIN_SET;
    static uint8_t K_7_last = GPIO_PIN_SET;
    static uint8_t K_8_last = GPIO_PIN_SET;
    static uint8_t K_9_last = GPIO_PIN_SET;
    
    static uint8_t K_DOT_last = GPIO_PIN_SET;
    static uint8_t K_NUM_last = GPIO_PIN_SET;
    static uint8_t K_DIVISION_last = GPIO_PIN_SET;
    static uint8_t K_MULTIPLE_last = GPIO_PIN_SET;
    static uint8_t K_PLUS_last = GPIO_PIN_SET;
    static uint8_t K_MINUS_last = GPIO_PIN_SET;
    static uint8_t K_ENTER_last = GPIO_PIN_SET;
    static uint8_t K_BACK_last = GPIO_PIN_SET;
    
    uint32_t current_tick = HAL_GetTick();

    // Check debounce timeout
    if (current_tick - last_scan_time < KEY_DEBOUNCE_MS)
    {
        return KEY_EVENT_NONE;
    }
    last_scan_time = current_tick;

    // Read all pins
    uint8_t K_0_now = HAL_GPIO_ReadPin(K_0_GPIO_Port, K_0_Pin);
    uint8_t K_1_now = HAL_GPIO_ReadPin(K_1_GPIO_Port, K_1_Pin);
    uint8_t K_2_now = HAL_GPIO_ReadPin(K_2_GPIO_Port, K_2_Pin);
    uint8_t K_3_now = HAL_GPIO_ReadPin(K_3_GPIO_Port, K_3_Pin);
    uint8_t K_4_now = HAL_GPIO_ReadPin(K_4_GPIO_Port, K_4_Pin);
    uint8_t K_5_now = HAL_GPIO_ReadPin(K_5_GPIO_Port, K_5_Pin);
    uint8_t K_6_now = HAL_GPIO_ReadPin(K_6_GPIO_Port, K_6_Pin);
    uint8_t K_7_now = HAL_GPIO_ReadPin(K_7_GPIO_Port, K_7_Pin);
    uint8_t K_8_now = HAL_GPIO_ReadPin(K_8_GPIO_Port, K_8_Pin);
    uint8_t K_9_now = HAL_GPIO_ReadPin(K_9_GPIO_Port, K_9_Pin);

    uint8_t K_DOT_now = HAL_GPIO_ReadPin(K_DOT_GPIO_Port, K_DOT_Pin);
    uint8_t K_NUM_now = HAL_GPIO_ReadPin(K_NUM_GPIO_Port, K_NUM_Pin);
    uint8_t K_DIVISION_now = HAL_GPIO_ReadPin(K_DIVISION_GPIO_Port, K_DIVISION_Pin);
    uint8_t K_MULTIPLE_now = HAL_GPIO_ReadPin(K_MULTIPLE_GPIO_Port, K_MULTIPLE_Pin);
    uint8_t K_PLUS_now = HAL_GPIO_ReadPin(K_PLUS_GPIO_Port, K_PLUS_Pin);
    uint8_t K_MINUS_now = HAL_GPIO_ReadPin(K_MINUS_GPIO_Port, K_MINUS_Pin);
    uint8_t K_ENTER_now = HAL_GPIO_ReadPin(K_ENTER_GPIO_Port, K_ENTER_Pin);
    uint8_t K_BACK_now = HAL_GPIO_ReadPin(K_BACK_GPIO_Port, K_BACK_Pin);

    KeyEvent event = KEY_EVENT_NONE;

    // Priority encoding for key press detection (falling edge)
    if (K_0_last == GPIO_PIN_SET && K_0_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_0_PRESSED;
    } else if (K_1_last == GPIO_PIN_SET && K_1_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_1_PRESSED;
    } else if (K_2_last == GPIO_PIN_SET && K_2_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_2_PRESSED;
    } else if (K_3_last == GPIO_PIN_SET && K_3_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_3_PRESSED;
    } else if (K_4_last == GPIO_PIN_SET && K_4_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_4_PRESSED;
    } else if (K_5_last == GPIO_PIN_SET && K_5_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_5_PRESSED;
    } else if (K_6_last == GPIO_PIN_SET && K_6_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_6_PRESSED;
    } else if (K_7_last == GPIO_PIN_SET && K_7_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_7_PRESSED;
    } else if (K_8_last == GPIO_PIN_SET && K_8_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_8_PRESSED;
    } else if (K_9_last == GPIO_PIN_SET && K_9_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_9_PRESSED;
    } else if (K_DOT_last == GPIO_PIN_SET && K_DOT_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_DOT_PRESSED;
    } else if (K_NUM_last == GPIO_PIN_SET && K_NUM_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_NUM_PRESSED;
    } else if (K_DIVISION_last == GPIO_PIN_SET && K_DIVISION_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_DIVISION_PRESSED;
    } else if (K_MULTIPLE_last == GPIO_PIN_SET && K_MULTIPLE_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_MULTIPLE_PRESSED;
    } else if (K_PLUS_last == GPIO_PIN_SET && K_PLUS_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_PLUS_PRESSED;
    } else if (K_MINUS_last == GPIO_PIN_SET && K_MINUS_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_MINUS_PRESSED;
    } else if (K_ENTER_last == GPIO_PIN_SET && K_ENTER_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_ENTER_PRESSED;
    } else if (K_BACK_last == GPIO_PIN_SET && K_BACK_now == GPIO_PIN_RESET) {
        event = KEY_EVENT_BACK_PRESSED;
    }

    // Update last status
    K_0_last = K_0_now;
    K_1_last = K_1_now;
    K_2_last = K_2_now;
    K_3_last = K_3_now;
    K_4_last = K_4_now;
    K_5_last = K_5_now;
    K_6_last = K_6_now;
    K_7_last = K_7_now;
    K_8_last = K_8_now;
    K_9_last = K_9_now;
    
    K_DOT_last = K_DOT_now;
    K_NUM_last = K_NUM_now;
    K_DIVISION_last = K_DIVISION_now;
    K_MULTIPLE_last = K_MULTIPLE_now;
    K_PLUS_last = K_PLUS_now;
    K_MINUS_last = K_MINUS_now;
    K_ENTER_last = K_ENTER_now;
    K_BACK_last = K_BACK_now;

    return event;
}